package org.telegram.messenger.tetogram;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.List;
public class AppearanceElementsTest {
    private static final String[] ALL={AppearanceElements.WALLPAPER,AppearanceElements.INCOMING,AppearanceElements.OUTGOING,AppearanceElements.HEADER,AppearanceElements.INPUT,AppearanceElements.LIST_ROW,AppearanceElements.LIST_BACKGROUND,AppearanceElements.PROFILE_NAME,AppearanceElements.PROFILE_STATUS,AppearanceElements.BANNER,AppearanceElements.SECTION};
    @Test public void everyElementHasRolesWithValidStoredNames(){for(String e:ALL){List<AppearanceElements.Role> roles=AppearanceElements.roles(e);assertFalse(e,roles.isEmpty());for(AppearanceElements.Role r:roles){AppearanceConfig.Style s=new AppearanceConfig.Style();s.color(false,r.name,1);s.color(true,r.name,2);}}assertTrue(AppearanceElements.roles("nope").isEmpty());assertTrue(AppearanceElements.roles(null).isEmpty());}
    @Test public void mainRoleIsTheBubbleOrSurface(){assertEquals("chat_outBubble",AppearanceElements.roles(AppearanceElements.OUTGOING).get(0).name);assertEquals("chat_inBubble",AppearanceElements.roles(AppearanceElements.INCOMING).get(0).name);assertEquals("actionBarDefault",AppearanceElements.roles(AppearanceElements.HEADER).get(0).name);}
    @Test public void textRolesPointAtTheirBackground(){List<AppearanceElements.Role> out=AppearanceElements.roles(AppearanceElements.OUTGOING);assertEquals(-1,AppearanceElements.backgroundOf(out,0));assertEquals(0,AppearanceElements.backgroundOf(out,1));List<AppearanceElements.Role> name=AppearanceElements.roles(AppearanceElements.PROFILE_NAME);assertEquals(-1,AppearanceElements.backgroundOf(name,0));List<AppearanceElements.Role> section=AppearanceElements.roles(AppearanceElements.SECTION);assertEquals(2,AppearanceElements.backgroundOf(section,3));}
    @Test public void elementsBelongToTheirSurface(){assertTrue(AppearanceElements.onSurface(AppearanceElements.HEADER,0));assertTrue(AppearanceElements.onSurface(AppearanceElements.OUTGOING,3));assertFalse(AppearanceElements.onSurface(AppearanceElements.OUTGOING,1));assertTrue(AppearanceElements.onSurface(AppearanceElements.LIST_ROW,5));assertTrue(AppearanceElements.onSurface(AppearanceElements.SECTION,4));assertFalse(AppearanceElements.onSurface(AppearanceElements.SECTION,1));assertTrue(AppearanceElements.onSurface(AppearanceElements.BANNER,2));assertFalse(AppearanceElements.onSurface(null,0));}
    @Test public void scopesLimitWhatCanBeChanged(){assertTrue(AppearanceElements.allowed(AppearanceElements.PROFILE_NAME,"global"));assertTrue(AppearanceElements.allowed(AppearanceElements.BANNER,"profile:5"));assertFalse(AppearanceElements.allowed(AppearanceElements.BANNER,"chat:5"));assertFalse(AppearanceElements.allowed(AppearanceElements.OUTGOING,"profile:5"));assertTrue(AppearanceElements.allowed(AppearanceElements.OUTGOING,"chat:5"));assertFalse(AppearanceElements.allowed(AppearanceElements.SECTION,"chat:5"));assertTrue(AppearanceElements.allowed(AppearanceElements.SECTION,"section:b8348b88-aac9-4f3c-85f7-bb44b7e2b967"));}
}
